import{_ as e,a as o,b as t,c as l,d as n,e as s,f as r,g as i,h as k,j as p,i as u}from"./chunks/m_ukol_z_fotky.CKuNbe3o.js";import{_ as v}from"./chunks/m_edit_fotky2.IVXZ5228.js";import{_ as d,o as m,c as z,aa as y}from"./chunks/framework.BAs_AphD.js";const N=JSON.parse('{"title":"Nový úkol v mobilu","description":"","frontmatter":{"title":"Nový úkol v mobilu","wiki":"cs:tickets:m_task_new"},"headers":[],"relativePath":"tickets/m_task_new.md","filePath":"tickets/m_task_new.md","lastUpdated":1794209661000}'),h={name:"tickets/m_task_new.md"};function b(c,a,g,f,j,_){return m(),z("div",null,[...a[0]||(a[0]=[y('<h1 id="novy-ukol-v-mobilu" tabindex="-1">Nový úkol v mobilu <a class="header-anchor" href="#novy-ukol-v-mobilu" aria-label="Permalink to &quot;Nový úkol v mobilu&quot;">​</a></h1><p>V mobilní aplikaci zadáte úkol přímo na místě: vyplníte formulář, nebo začnete fotkou vady, místem na výkresu či záznamem v deníku. Tato stránka popisuje, jak se úkol zakládá na telefonu; co znamenají jednotlivá pole, najdete na stránce <a href="/buildary-help-preview/tickets/task_new">Zadat úkol</a>.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/notifikace-mobil">Nastavit upozornění a zadávat úkoly z mobilu</a> a <a href="/buildary-help-preview/akademie/novy-ukol">Zadat vadu nebo úkol do výkresu</a> v Akademii.</p><h2 id="zpusoby-jak-ukol-zalozit" tabindex="-1">Způsoby, jak úkol založit <a class="header-anchor" href="#zpusoby-jak-ukol-zalozit" aria-label="Permalink to &quot;Způsoby, jak úkol založit&quot;">​</a></h2><ul><li><strong>Formulářem</strong> – v Seznamu úkolů klepněte na tlačítko <strong>+</strong> vpravo dole.</li><li><strong>Z fotky</strong> – v Seznamu úkolů klepněte na tlačítko s fotoaparátem nad tlačítkem <strong>+</strong>. Viz <a href="#ukol-z-fotky">Úkol z fotky</a>.</li><li><strong>Z výkresu nebo mapy</strong> – viz <a href="#ukol-z-vykresu-nebo-mapy">Úkol z výkresu nebo mapy</a>.</li><li><strong>Ze záznamu v deníku</strong> – viz <a href="#ukol-ze-zaznamu-v-deniku">Úkol ze záznamu v deníku</a>.</li></ul><p>Pro uložení stačí vyplnit <strong>Předmět</strong> a vybrat Řešitele. Úkol uložíte modrým tlačítkem s fajfkou vpravo dole.</p><h2 id="vyplnit-ukol" tabindex="-1">Vyplnit úkol <a class="header-anchor" href="#vyplnit-ukol" aria-label="Permalink to &quot;Vyplnit úkol&quot;">​</a></h2><p>Pod polem <strong>Předmět</strong> jsou čtyři záložky: základní údaje, přílohy, výkresy a mapa, účastníci. Vyplňte nejdřív základní údaje a pak přejděte na další záložky.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+e+'" alt="Prázdný formulář Nový úkol v mobilu" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+o+'" alt="Formulář nového úkolu s vyplněnými základními údaji" loading="lazy"></figure></div><h3 id="zakladni-udaje" tabindex="-1">Základní údaje <a class="header-anchor" href="#zakladni-udaje" aria-label="Permalink to &quot;Základní údaje&quot;">​</a></h3><ul><li><strong>Předmět</strong> – krátký a výstižný název úkolu.</li><li><strong>Popis úkolu</strong> – podrobnosti, které z předmětu nejsou zřejmé.</li><li><strong>Kategorie</strong> – vyberte jednu z nabídky.</li><li><strong>Stav</strong> – předvyplněný je stav <strong>Nezahájeno</strong>.</li><li><strong>Priorita</strong> – předvyplněná je <strong>Střední</strong>.</li><li><strong>Štítky</strong> – můžete vybrat jeden nebo více, pokud je stavba má nastavené.</li><li><strong>Plánovaný termín</strong> – začátek je předvyplněný na dnešek, konec za 7 dní. Oba termíny můžete změnit. Skutečný termín doplní aplikace sama.</li></ul><div class="tip custom-block"><p class="custom-block-title">Diktujte místo psaní</p><p>Popis nemusíte psát. Klepněte na ikonu mikrofonu na klávesnici telefonu a mluvte – telefon řeč převede na text. Funguje to v každém textovém poli.</p></div><h3 id="prilohy" tabindex="-1">Přílohy <a class="header-anchor" href="#prilohy" aria-label="Permalink to &quot;Přílohy&quot;">​</a></h3><p>Přílohy přidáte ikonami v dolní liště. Fungují na každé záložce formuláře; přidaná příloha se vždy uloží na záložku příloh.</p><ul><li><strong>Fotoaparát</strong> – vyfotíte fotku rovnou do úkolu.</li><li><strong>Galerie</strong> – vyberete jednu nebo více fotek uložených v telefonu.</li><li><strong>Kancelářská sponka</strong> – nabídne <strong>Pořídit foto</strong>, <strong>Pořídit video</strong>, <strong>Nahrát foto</strong>, <strong>Nahrát video</strong> a <strong>Nahrát přílohu</strong> (libovolný soubor z telefonu).</li></ul><p>Fotek i souborů můžete vybrat několik najednou, i na iPhonu.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+t+'" alt="Záložka příloh nového úkolu s dolní lištou fotoaparát, galerie a sponka" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+l+'" alt="Nabídka sponky: Pořídit foto, Pořídit video, Nahrát foto, Nahrát video, Nahrát přílohu" loading="lazy"></figure></div><p>Fotky a videa pořízená v aplikaci se neukládají do telefonu, ale rovnou na server. Nezabírají vám tak místo v paměti.</p><h3 id="vykresy-a-mapa" tabindex="-1">Výkresy a mapa <a class="header-anchor" href="#vykresy-a-mapa" aria-label="Permalink to &quot;Výkresy a mapa&quot;">​</a></h3><p>Na této záložce určíte, kde na stavbě úkol je – značkou ve výkresu, polohou v mapě, nebo obojím. Výkresy musí být nahrané v nastavení stavby na webu, viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+n+'" alt="Záložka výkresů a mapy: Část stavby a výkres, pole Část stavby, Vyber výkres a Umístění v mapě" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+s+'" alt="Zvětšený výkres se značkami úkolu" loading="lazy"></figure></div><p><strong>Vybrat výkres</strong> – v části <strong>Část stavby a výkres</strong> máte tři možnosti:</p><ul><li>do pole <strong>Část stavby</strong> začněte psát název a vyberte z nabídky, nebo rozbalte celý seznam šipkou,</li><li>ikonou vrstev vedle pole otevřete části stavby ve stromové struktuře i s počtem výkresů,</li><li>tlačítkem <strong>Vyber výkres</strong> vyberete přímo výkres podle náhledů.</li></ul><p><strong>Zadat značky</strong> – klepněte na výkres nebo na <strong>Zadej značky</strong>. Výkres se otevře zvětšený; můžete ho posouvat a přibližovat. Na místě vady podržte prst, dokud se značka neobjeví. Značek může být víc. Značku přesunete tak, že na ní podržíte prst a přetáhnete ji; smažete ji přetažením do koše dole. Výkres se značkami uložte tlačítkem <strong>OK</strong> vpravo nahoře.</p><p><strong>Umístění v mapě</strong> – pod výkresem je mapa. Klepněte na místo úkolu, nebo klepněte na ikonu zaměřovače a značka se umístí na polohu telefonu. Špatně umístěnou značku přesunete klepnutím na správné místo.</p><p>Místo stavby a GPS souřadnice aplikace podle značky doplní sama.</p><figure class="shot" style="--w:260px;"><img src="'+r+'" alt="Mapa se značkou místa úkolu a ikonou zaměřovače" loading="lazy"></figure><h3 id="ucastnici" tabindex="-1">Účastníci <a class="header-anchor" href="#ucastnici" aria-label="Permalink to &quot;Účastníci&quot;">​</a></h3><p>Vyberte <strong>Řešitele</strong> a případně <strong>Schvalovatele</strong>. Nabídka obsahuje členy projektového týmu stavby; do každé role můžete vybrat víc lidí.</p><figure class="shot" style="--w:260px;"><img src="'+i+'" alt="Záložka účastníků s výběrem Řešitelů a Schvalovatelů" loading="lazy"></figure><p>Pokud úkol odpovídá některému pravidlu stavby, aplikace Řešitele a Schvalovatele doplní sama. Výběr můžete změnit. Pravidla se nastavují na webu – viz <a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a>.</p><h2 id="ukol-z-fotky" tabindex="-1">Úkol z fotky <a class="header-anchor" href="#ukol-z-fotky" aria-label="Permalink to &quot;Úkol z fotky&quot;">​</a></h2><p>Nejrychlejší cesta, jak zadat vadu: vyfotíte ji, případně do fotky zakreslíte, a doplníte údaje.</p><ol><li>V Seznamu úkolů klepněte na tlačítko s fotoaparátem.</li><li>Vyfoťte vadu a snímek potvrďte. Fotka se otevře v editoru – můžete ji rovnou upravit, viz <a href="#upravit-fotku">Upravit fotku</a>.</li><li>Klepněte na modré tlačítko s fajfkou vpravo dole. Otevře se formulář nového úkolu s fotkou v přílohách.</li><li>Vyplňte alespoň <strong>Předmět</strong> a Řešitele a úkol uložte.</li></ol><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+k+'" alt="Pořízená fotka vady v editoru před založením úkolu" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+p+'" alt="Formulář nového úkolu s fotkou vloženou do příloh" loading="lazy"></figure></div><p>Nelíbí se vám snímek? Klepněte na ikonu fotoaparátu vlevo dole a vyfoťte nový – původní se nahradí.</p><div class="warning custom-block"><p class="custom-block-title">Šipka zpět fotku zahodí</p><p>Šipka zpět v záhlaví celé zakládání zruší a vrátí vás do Seznamu úkolů. Fotka se neuloží.</p></div><h3 id="upravit-fotku" tabindex="-1">Upravit fotku <a class="header-anchor" href="#upravit-fotku" aria-label="Permalink to &quot;Upravit fotku&quot;">​</a></h3><p>Editor se otevře po vyfocení úkolu z fotky. U úkolu, který už existuje, ho otevřete volbou <strong>Upravit</strong> v nabídce fotky v přílohách – jen u fotek, které jste přidali vy.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+u+'" alt="Editor fotky s lištou nástrojů pod snímkem" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+v+'" alt="Rozbalené možnosti vybraného nástroje pod snímkem" loading="lazy"></figure></div><p>V liště pod fotkou jsou nástroje:</p><ul><li>oříznutí, otočení a zrcadlové překlopení,</li><li>tvary, čáry a šipky s volbou barvy a tloušťky,</li><li>text s volbou barvy a písma,</li><li>pero s volbou barvy a tloušťky,</li><li>úprava jasu, kontrastu, ostrosti a dalších vlastností.</li></ul><p>Po klepnutí na nástroj se jeho možnosti rozbalí pod snímkem.</p><div class="warning custom-block"><p class="custom-block-title">Každou úpravu potvrďte</p><p>Po každé úpravě klepněte na fajfku nad fotkou a teprve pak se šipkou pod snímkem vraťte k nástrojům. Bez potvrzení se úprava ztratí.</p></div><p>Šipkami nad snímkem se vracíte o krok zpět a vpřed. Ikona vpravo nad snímkem vrátí fotku do původní podoby – všechny úpravy se smažou a vrátit je nejde.</p><p>Upravenou fotku uložíte modrým tlačítkem s fajfkou vpravo dole. Šipka zpět v záhlaví editor zavře bez uložení změn.</p><h2 id="ukol-z-vykresu-nebo-mapy" tabindex="-1">Úkol z výkresu nebo mapy <a class="header-anchor" href="#ukol-z-vykresu-nebo-mapy" aria-label="Permalink to &quot;Úkol z výkresu nebo mapy&quot;">​</a></h2><p>V menu aplikace zvolte <strong>Management úkolů</strong> → <strong>Výkresy a mapa</strong> a na výkresu nebo v mapě označte místo, kde je potřeba něco vyřešit. Úkol je pak s tímto místem rovnou propojený. Jak se v této obrazovce zobrazují existující úkoly, popisuje <a href="/buildary-help-preview/tickets/m_task_grid">Úkoly v mobilu</a>.</p><h2 id="ukol-ze-zaznamu-v-deniku" tabindex="-1">Úkol ze záznamu v deníku <a class="header-anchor" href="#ukol-ze-zaznamu-v-deniku" aria-label="Permalink to &quot;Úkol ze záznamu v deníku&quot;">​</a></h2><p>Úkol můžete založit i přímo ze záznamu ve stavebním deníku – z provedené práce nebo z Dalšího záznamu. Údaje ze záznamu nemusíte přepisovat a úkol zůstane se záznamem propojený. U záznamu pak uvidíte i úkoly, které z něj vznikly.</p><p>Na stavbě musí být zapnutý Management úkolů. Jak to funguje na webu, popisuje <a href="/buildary-help-preview/diary/dailyentriesothers#ukol-k-zaznamu">Další záznamy</a>, práci s deníkem v telefonu <a href="/buildary-help-preview/diary/m_dailyentries">Denní záznamy v mobilu</a>.</p><h2 id="bez-signalu" tabindex="-1">Bez signálu <a class="header-anchor" href="#bez-signalu" aria-label="Permalink to &quot;Bez signálu&quot;">​</a></h2><p>Nové úkoly můžete zakládat i bez připojení. Ostatní je uvidí až po synchronizaci – viz <a href="/buildary-help-preview/diary/m_offline">Práce bez signálu</a>.</p>',53)])])}const q=d(h,[["render",b]]);export{N as __pageData,q as default};
